// Des: Object store interface and S3-compatible client (SigV4)
// Flo: sign request > send via transport > check status > put/get/delete/list with paging
// I/O: key + bytes (sync, purge) > bytes or key list; works for B2, R2, Tigris via host + region
// ===================================================================
const std = @import("std"); const base = @import("nt-vend-base.zig"); const s3v4 = @import("sy-clou-s3v4.zig");
const CF = .{ .pagz = 10 };
pub const Obj = struct { key: []const u8, size: u64 };
pub const Store = struct { ctx: *anyopaque, put: *const fn (ctx: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, key: []const u8, bytes: []const u8) anyerror!void, get: *const fn (ctx: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, key: []const u8) anyerror![]u8, del: *const fn (ctx: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, key: []const u8) anyerror!void, list: *const fn (ctx: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, prefix: []const u8) anyerror![]Obj };
pub const Pair = struct { akey: []const u8, skey: []const u8 };
pub fn keyPair(text: []const u8) !Pair { var iter = std.mem.splitScalar(u8, text, '\n'); const akey = std.mem.trim(u8, iter.next() orelse return error.NoKey, " \t\r"); const skey = std.mem.trim(u8, iter.next() orelse return error.NoKey, " \t\r"); if (akey.len == 0 or skey.len == 0) return error.NoKey; return .{ .akey = akey, .skey = skey }; }
pub const S3 = struct { cred: s3v4.Cred, bukt: []const u8, send: base.Send, gpaz: std.mem.Allocator,
pub fn store(self: *S3) Store { return .{ .ctx = self, .put = putz, .get = getz, .del = delz, .list = listz }; }
fn pathOf(self: *S3, aren: std.mem.Allocator, key: []const u8) ![]u8 { var outp: std.ArrayList(u8) = .empty; try outp.append(aren, '/'); try outp.appendSlice(aren, self.bukt); if (key.len > 0) { var iter = std.mem.splitScalar(u8, key, '/'); while (iter.next()) |seg| { try outp.append(aren, '/'); try outp.appendSlice(aren, try base.pctEnc(aren, seg)); } } return outp.toOwnedSlice(aren); }
fn call(self: *S3, aren: std.mem.Allocator, iozz: std.Io, meth: []const u8, key: []const u8, query: []const u8, body: []const u8) !base.Back { const path = try self.pathOf(aren, key); var dbuf: [16]u8 = undefined; const date = try aren.dupe(u8, s3v4.dateNow(&dbuf, std.Io.Clock.real.now(iozz).toMilliseconds())); const sig = try s3v4.sigMake(aren, self.cred, meth, path, query, body, date); const extra = try aren.alloc(base.Hdr, 2); extra[0] = .{ .name = "x-amz-date", .valu = date }; extra[1] = .{ .name = "x-amz-content-sha256", .valu = sig.phsh }; const urlz = try std.fmt.allocPrint(aren, "https://{s}{s}{s}{s}", .{ self.cred.host, path, if (query.len > 0) "?" else "", query }); return self.send.call(self.send.ctx, self.gpaz, iozz, .{ .post = false, .urlz = urlz, .auth = sig.auth, .body = body, .meth = meth, .extra = extra }); }
fn putz(ctx: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, key: []const u8, bytes: []const u8) anyerror!void { const self: *S3 = @ptrCast(@alignCast(ctx)); const back = try self.call(aren, iozz, "PUT", key, "", bytes); defer self.gpaz.free(back.body); if (back.code < 200 or back.code >= 300) return error.CloudHttp; }
fn getz(ctx: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, key: []const u8) anyerror![]u8 { const self: *S3 = @ptrCast(@alignCast(ctx)); const back = try self.call(aren, iozz, "GET", key, "", ""); defer self.gpaz.free(back.body); if (back.code < 200 or back.code >= 300) return error.CloudHttp; return aren.dupe(u8, back.body); }
fn delz(ctx: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, key: []const u8) anyerror!void { const self: *S3 = @ptrCast(@alignCast(ctx)); const back = try self.call(aren, iozz, "DELETE", key, "", ""); defer self.gpaz.free(back.body); if (back.code < 200 or back.code >= 300) return error.CloudHttp; }
fn tagz(src: []const u8, from: usize, tag: []const u8, aren: std.mem.Allocator) !?struct { text: []const u8, endz: usize } { const open = try std.fmt.allocPrint(aren, "<{s}>", .{tag}); const clos = try std.fmt.allocPrint(aren, "</{s}>", .{tag}); const beg = std.mem.findPos(u8, src, from, open) orelse return null; const endz = std.mem.findPos(u8, src, beg + open.len, clos) orelse return null; return .{ .text = src[beg + open.len .. endz], .endz = endz + clos.len }; }
fn listz(ctx: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, prefix: []const u8) anyerror![]Obj { const self: *S3 = @ptrCast(@alignCast(ctx)); var outp: std.ArrayList(Obj) = .empty; var token: []const u8 = ""; var pagez: usize = 0; while (pagez < CF.pagz) : (pagez += 1) { const query = if (token.len > 0) try std.fmt.allocPrint(aren, "continuation-token={s}&list-type=2&prefix={s}", .{ try base.pctEnc(aren, token), try base.pctEnc(aren, prefix) }) else try std.fmt.allocPrint(aren, "list-type=2&prefix={s}", .{try base.pctEnc(aren, prefix)}); const back = try self.call(aren, iozz, "GET", "", query, ""); defer self.gpaz.free(back.body); if (back.code < 200 or back.code >= 300) return error.CloudHttp; const xml = try aren.dupe(u8, back.body); var pos: usize = 0; while (try tagz(xml, pos, "Contents", aren)) |blk| { pos = blk.endz; const key = (try tagz(blk.text, 0, "Key", aren)) orelse continue; const siz = (try tagz(blk.text, 0, "Size", aren)) orelse continue; try outp.append(aren, .{ .key = key.text, .size = std.fmt.parseInt(u64, siz.text, 10) catch 0 }); } const trunc = (try tagz(xml, 0, "IsTruncated", aren)) orelse break; if (!std.mem.eql(u8, trunc.text, "true")) break; const nxt = (try tagz(xml, 0, "NextContinuationToken", aren)) orelse break; token = nxt.text; } return outp.toOwnedSlice(aren); } };
